    // -------------------------------------------------------------------------
    // 3. SAFE LOCALSTORAGE PERSISTENCE
    // -------------------------------------------------------------------------
    function loadSavedState() {
      try {
        const savedTheme = localStorage.getItem('r9a3_theme');
        if (savedTheme === 'dark') {
          document.documentElement.classList.add('dark');
          document.documentElement.classList.remove('light');
        }
        const savedUser = localStorage.getItem('r9a3_user');
        if (savedUser) {
          currentUser = JSON.parse(savedUser);
        }
      } catch (e) {
        // Ignore storage restrictions in sandboxed environments
      }
    }

    function saveUserState() {
      try {
        localStorage.setItem('r9a3_user', JSON.stringify(currentUser));
      } catch (e) {}
    }

    // -------------------------------------------------------------------------
    // 4. TOAST HELPER (REPLACES BLOCKED ALERT/CONFIRM)
    // -------------------------------------------------------------------------
    let toastTimer = null;
    function showToast(message, icon = '✅') {
      const box = document.getElementById('toastBox');
      const msgEl = document.getElementById('toastMessage');
      const iconEl = document.getElementById('toastIcon');
      if (!box || !msgEl || !iconEl) return;
      iconEl.textContent = icon;
      msgEl.textContent = message;
      box.classList.remove('hidden');
      if (toastTimer) clearTimeout(toastTimer);
      toastTimer = setTimeout(() => {
        box.classList.add('hidden');
      }, 3500);
    }

    // -------------------------------------------------------------------------
    // 5. THEME TOGGLE (NỀN TRẮNG / ĐEN)
    // -------------------------------------------------------------------------
    function updateThemeButtonUI() {
      const isDark = document.documentElement.classList.contains('dark');
      const iconEl = document.getElementById('themeIcon');
      if (iconEl) {
        iconEl.textContent = isDark ? '☀️' : '🌙';
      }
    }

    function toggleTheme() {
      const htmlEl = document.documentElement;
      const isDark = htmlEl.classList.contains('dark');
      if (isDark) {
        htmlEl.classList.remove('dark');
        htmlEl.classList.add('light');
        try { localStorage.setItem('r9a3_theme', 'light'); } catch (e) {}
        showToast('Đã chuyển sang giao diện Nền Trắng (Light Mode)', '☀️');
      } else {
        htmlEl.classList.add('dark');
        htmlEl.classList.remove('light');
        try { localStorage.setItem('r9a3_theme', 'dark'); } catch (e) {}
        showToast('Đã chuyển sang giao diện Nền Đen (Dark Mode)', '🌙');
      }
      updateThemeButtonUI();
    }

    // -------------------------------------------------------------------------
    // 6. LOGO 9A3 -> GO HOME (MAIN PAGE) & TAG FILTERING
    // -------------------------------------------------------------------------
    function goHome() {
      activeTag = 'Tất cả';
      sortMode = 'hot';
      const searchInput = document.getElementById('searchInput');
      const headerSelect = document.getElementById('headerTagFilter');
      if (searchInput) searchInput.value = '';
      if (headerSelect) headerSelect.value = 'Tất cả';
      renderTagBars();
      renderFeed();
      window.scrollTo({ top: 0, behavior: 'smooth' });
      showToast('Đã về Trang chủ r/9A3AnChau', '🏠');
    }

    function selectTag(tagName) {
      activeTag = tagName;
      const headerSelect = document.getElementById('headerTagFilter');
      if (headerSelect) headerSelect.value = tagName;
      renderTagBars();
      renderFeed();
    }

    function selectTagFromDropdown(tagName) {
      selectTag(tagName);
      showToast(`Đang lọc theo chủ đề: ${tagName}`, '🏷️');
    }

    function filterByNav(mode) {
      if (mode === 'popular') {
        activeTag = 'Tất cả';
        setSortMode('hot');
        showToast('Đang hiển thị các bài đăng Thịnh hành nhất', '🔥');
      } else if (mode === 'toprated') {
        activeTag = 'Tất cả';
        setSortMode('rating');
        showToast('Đang xếp theo đánh giá 0-5 Sao cao nhất', '⭐');
      }
    }

    function handleSearchAndFilter() {
      const searchInput = document.getElementById('searchInput');
      const clearBtn = document.getElementById('clearSearchBtn');
      if (searchInput && clearBtn) {
        if (searchInput.value.trim().length > 0) {
          clearBtn.classList.remove('hidden');
        } else {
          clearBtn.classList.add('hidden');
        }
      }
      renderFeed();
    }

    function clearSearch() {
      const searchInput = document.getElementById('searchInput');
      const clearBtn = document.getElementById('clearSearchBtn');
      if (searchInput) searchInput.value = '';
      if (clearBtn) clearBtn.classList.add('hidden');
      renderFeed();
    }

    function setSortMode(mode) {
      sortMode = mode;
      const hotBtn = document.getElementById('sortHotBtn');
      const newBtn = document.getElementById('sortNewBtn');
      const ratingBtn = document.getElementById('sortRatingBtn');

      const activeClass = 'px-3 py-1.5 rounded-full text-xs font-bold bg-slate-900 text-white dark:bg-white dark:text-slate-900 transition';
      const inactiveClass = 'px-3 py-1.5 rounded-full text-xs font-semibold text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-[#22333A] transition';

      if (hotBtn) hotBtn.className = mode === 'hot' ? activeClass : inactiveClass;
      if (newBtn) newBtn.className = mode === 'new' ? activeClass : inactiveClass;
      if (ratingBtn) ratingBtn.className = mode === 'rating' ? activeClass : inactiveClass;

      renderFeed();
    }

    // -------------------------------------------------------------------------
    // 7. RENDER TAG BARS (HORIZONTAL + LEFT SIDEBAR)
    // -------------------------------------------------------------------------
    function renderTagBars() {
      const horizContainer = document.getElementById('horizontalTagBar');
      const sidebarContainer = document.getElementById('sidebarTagList');

      if (horizContainer) {
        horizContainer.innerHTML = ALL_TAGS.map(t => {
          const isSelected = activeTag === t.name;
          const btnStyle = isSelected
            ? 'bg-[#FF4500] text-white shadow-sm font-bold'
            : 'bg-white dark:bg-[#1A282D] text-slate-700 dark:text-slate-200 hover:bg-orange-50 dark:hover:bg-[#22333A] border border-slate-200 dark:border-[#2A3C42] font-medium';
          return `
            <button
              type="button"
              onclick="selectTag('${t.name}')"
              class="shrink-0 px-3 py-1 rounded-full text-xs flex items-center gap-1.5 transition ${btnStyle}"
            >
              <span>${t.icon}</span>
              <span>${t.name}</span>
            </button>
          `;
        }).join('');
      }

      if (sidebarContainer) {
        sidebarContainer.innerHTML = ALL_TAGS.filter(t => t.name !== 'Tất cả').map(t => {
          const count = posts.filter(p => p.tag === t.name).length;
          const isSelected = activeTag === t.name;
          const rowClass = isSelected
            ? 'bg-orange-50 dark:bg-orange-950/40 text-[#FF4500] font-bold'
            : 'text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-[#22333A] font-medium';
          return `
            <button
              type="button"
              onclick="selectTag('${t.name}')"
              class="w-full flex items-center justify-between px-3 py-1.5 rounded-xl text-xs transition ${rowClass}"
            >
              <span class="flex items-center gap-2.5 truncate">
                <span>${t.icon}</span>
                <span class="truncate">${t.name}</span>
              </span>
              <span class="text-[10px] px-2 py-0.5 rounded-full bg-slate-100 dark:bg-[#0B1416] text-slate-500">${count}</span>
            </button>
          `;
        }).join('');
      }

      const badge = document.getElementById('activeFilterBadge');
      const resetBtn = document.getElementById('resetFilterBtn');
      if (badge) {
        badge.textContent = `Đang xem: ${activeTag}`;
      }
      if (resetBtn) {
        if (activeTag !== 'Tất cả') {
          resetBtn.classList.remove('hidden');
        } else {
          resetBtn.classList.add('hidden');
        }
      }
    }

    // -------------------------------------------------------------------------
    // 8. RENDER PINNED CLASS ANNOUNCEMENTS & MAIN POSTS FEED
    // -------------------------------------------------------------------------
    function getTagMeta(tagName) {
      return ALL_TAGS.find(t => t.name === tagName) || { name: tagName, icon: '📌', color: 'bg-slate-100 text-slate-700' };
    }

    function escapeHtml(str) {
      return String(str || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
    }

    function renderAnnouncements() {
      const listEl = document.getElementById('pinnedAnnouncementsList');
      if (!listEl) return;
      const announcements = posts.filter(p => p.tag === 'Thông báo' || p.isAnnouncement).slice(0, 2);
      if (announcements.length === 0) {
        listEl.innerHTML = `<div class="text-xs text-slate-500">Chưa có thông báo ghim nào.</div>`;
        return;
      }
      listEl.innerHTML = announcements.map(a => `
        <div class="p-3 rounded-xl bg-white/90 dark:bg-[#1A282D]/90 border border-orange-200/80 dark:border-[#2A3C42] flex items-start justify-between gap-3">
          <div class="space-y-0.5">
            <div class="flex items-center gap-2">
              <span class="font-bold text-xs sm:text-sm text-slate-900 dark:text-white">${escapeHtml(a.title)}</span>
            </div>
            <p class="text-xs text-slate-600 dark:text-slate-300 line-clamp-2">${escapeHtml(a.content)}</p>
            <div class="text-[10px] text-slate-400">Đăng bởi @${escapeHtml(a.authorUsername)} • ${escapeHtml(a.timeLabel)}</div>
          </div>
          <button
            type="button"
            onclick="scrollToPost('${a.id}')"
            class="shrink-0 px-2.5 py-1 rounded-lg bg-orange-100 dark:bg-orange-950/60 text-[#FF4500] text-xs font-bold hover:underline"
          >
            Xem
          </button>
        </div>
      `).join('');
    }

    function scrollToPost(postId) {
      const el = document.getElementById('post-card-' + postId);
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        el.classList.add('ring-2', 'ring-[#FF4500]');
        setTimeout(() => el.classList.remove('ring-2', 'ring-[#FF4500]'), 2200);
      } else {
        activeTag = 'Tất cả';
        renderTagBars();
        renderFeed();
      }
    }

    function renderFeed() {
      renderAnnouncements();

      const totalStat = document.getElementById('totalPostsStat');
      if (totalStat) totalStat.textContent = String(posts.length);

      const container = document.getElementById('postsFeedContainer');
      if (!container) return;

      const query = (document.getElementById('searchInput')?.value || '').trim().toLowerCase();

      let filtered = posts.filter(post => {
        const matchesTag = activeTag === 'Tất cả' || post.tag === activeTag;
        const matchesSearch = !query ||
          post.title.toLowerCase().includes(query) ||
          post.content.toLowerCase().includes(query) ||
          post.tag.toLowerCase().includes(query) ||
          post.authorName.toLowerCase().includes(query) ||
          post.authorUsername.toLowerCase().includes(query);
        return matchesTag && matchesSearch;
      });

      filtered.sort((a, b) => {
        if (sortMode === 'new') return b.createdAt - a.createdAt;
        if (sortMode === 'rating') {
          const avgA = a.ratingCount > 0 ? a.ratingSum / a.ratingCount : 0;
          const avgB = b.ratingCount > 0 ? b.ratingSum / b.ratingCount : 0;
          return avgB - avgA;
        }
        return b.score - a.score;
      });

      if (filtered.length === 0) {
        container.innerHTML = `
          <div class="bg-white dark:bg-[#1A282D] rounded-2xl border border-slate-200 dark:border-[#2A3C42] p-10 text-center space-y-3">
            <div class="text-4xl">🔍</div>
            <h3 class="font-bold text-base">Không tìm thấy bài đăng nào phù hợp</h3>
            <p class="text-xs text-slate-500 dark:text-slate-400">Thử tìm từ khoá khác, chọn lại bộ lọc môn học hoặc đăng bài mới đầu tiên cho chủ đề này!</p>
            <button type="button" onclick="openCreatePostModal(activeTag !== 'Tất cả' ? activeTag : 'Hỏi đáp')" class="px-4 py-2 rounded-full bg-[#FF4500] text-white text-xs font-bold">
              ＋ Đăng bài vào mục này
            </button>
          </div>
        `;
        return;
      }

      container.innerHTML = filtered.map(post => {
        const tagMeta = getTagMeta(post.tag);
        const avgRating = post.ratingCount > 0 ? (post.ratingSum / post.ratingCount).toFixed(1) : '0.0';
        const upActive = post.userVote === 1 ? 'active' : '';
        const downActive = post.userVote === -1 ? 'active' : '';

        // Media HTML (Image or Video <100MB)
        let mediaHtml = '';
        if (post.media && post.media.url) {
          if (post.media.type === 'video') {
            mediaHtml = `
              <div class="mt-3 rounded-2xl overflow-hidden bg-black border border-slate-200 dark:border-[#2A3C42]">
                <video controls class="w-full max-h-96 object-contain">
                  <source src="${post.media.url}">
                </video>
                <div class="px-3 py-1.5 bg-slate-900 text-[11px] text-slate-300 flex justify-between">
                  <span>🎬 ${escapeHtml(post.media.name || 'Video lớp 9A3')}</span>
                  <span>${escapeHtml(post.media.sizeMB || '< 100MB')}</span>
                </div>
              </div>
            `;
          } else {
            mediaHtml = `
              <div class="mt-3 rounded-2xl overflow-hidden bg-slate-100 dark:bg-[#0B1416] border border-slate-200 dark:border-[#2A3C42]">
                <img src="${post.media.url}" alt="${escapeHtml(post.title)}" class="w-full max-h-[420px] object-cover">
              </div>
            `;
          }
        }

        // 0-5 Star Rating Buttons (0★ to 5★)
        const starButtonsHtml = [0, 1, 2, 3, 4, 5].map(starVal => {
          const isSelected = post.userRating === starVal;
          const activeClasses = isSelected
            ? 'bg-amber-400 text-slate-950 font-extrabold border-amber-500 shadow-sm'
            : 'bg-slate-100 dark:bg-[#0B1416] text-slate-600 dark:text-slate-300 hover:bg-amber-100 dark:hover:bg-amber-950/50 border-slate-200 dark:border-[#2A3C42]';
          return `
            <button
              type="button"
              onclick="ratePost('${post.id}', ${starVal})"
              class="star-btn px-2 py-0.5 rounded-lg text-[11px] border ${activeClasses}"
              title="Đánh giá ${starVal}/5 sao"
            >
              ${starVal}★
            </button>
          `;
        }).join('');

        // Comments list HTML
        const commentsHtml = post.comments.map(c => `
          <div class="p-3 rounded-xl bg-slate-50 dark:bg-[#121D21] border border-slate-200/70 dark:border-[#2A3C42] space-y-1">
            <div class="flex items-center justify-between">
              <span class="text-xs font-bold text-slate-800 dark:text-slate-200">${escapeHtml(c.author)}</span>
              <span class="text-[10px] text-slate-400">${escapeHtml(c.time)}</span>
            </div>
            <p class="text-xs sm:text-sm text-slate-700 dark:text-slate-300">${escapeHtml(c.text)}</p>
          </div>
        `).join('');

        return `
          <article id="post-card-${post.id}" class="bg-white dark:bg-[#1A282D] rounded-2xl border border-slate-200 dark:border-[#2A3C42] shadow-sm hover:border-slate-300 dark:hover:border-slate-600 transition overflow-hidden">
            <div class="flex">

              <!-- LEFT VOTE COLUMN (REDDIT UPVOTE / DOWNVOTE) -->
              <div class="w-12 sm:w-14 bg-slate-50/70 dark:bg-[#152126] border-r border-slate-100 dark:border-[#2A3C42] flex flex-col items-center py-3 gap-1 shrink-0">
                <button
                  type="button"
                  onclick="votePost('${post.id}', 1)"
                  class="vote-btn-up ${upActive} w-8 h-8 rounded-lg flex items-center justify-center text-slate-500 hover:bg-orange-100 dark:hover:bg-orange-950/50 transition"
                  title="Upvote bài đăng"
                >
                  ▲
                </button>
                <span class="font-extrabold text-xs sm:text-sm ${post.userVote === 1 ? 'text-[#FF4500]' : post.userVote === -1 ? 'text-indigo-400' : 'text-slate-800 dark:text-slate-200'}">
                  ${post.score}
                </span>
                <button
                  type="button"
                  onclick="votePost('${post.id}', -1)"
                  class="vote-btn-down ${downActive} w-8 h-8 rounded-lg flex items-center justify-center text-slate-500 hover:bg-indigo-100 dark:hover:bg-indigo-950/50 transition"
                  title="Downvote bài đăng"
                >
                  ▼
                </button>
              </div>

              <!-- MAIN POST CONTENT -->
              <div class="flex-1 p-3.5 sm:p-4 min-w-0">

                <!-- Post Header: Author, Time & Subject Tag -->
                <div class="flex flex-wrap items-center justify-between gap-2 mb-2">
                  <div class="flex items-center gap-2 min-w-0">
                    <img src="${post.authorAvatar}" alt="Avatar" class="w-6 h-6 rounded-full object-cover">
                    <span class="text-xs font-bold text-slate-800 dark:text-slate-200 truncate">${escapeHtml(post.authorName)}</span>
                    <span class="text-[11px] text-slate-400 truncate">@${escapeHtml(post.authorUsername)} • ${escapeHtml(post.timeLabel)}</span>
                  </div>
                  <button
                    type="button"
                    onclick="selectTag('${post.tag}')"
                    class="px-2.5 py-0.5 rounded-full text-xs font-bold flex items-center gap-1 ${tagMeta.color}"
                  >
                    <span>${tagMeta.icon}</span>
                    <span>${escapeHtml(post.tag)}</span>
                  </button>
                </div>

                <!-- Post Title & Text Body -->
                <h2 class="font-extrabold text-base sm:text-lg text-slate-900 dark:text-white leading-snug mb-1.5">
                  ${escapeHtml(post.title)}
                </h2>
                <p class="text-xs sm:text-sm text-slate-700 dark:text-slate-300 whitespace-pre-line leading-relaxed">
                  ${escapeHtml(post.content)}
                </p>

                <!-- Attached Image or Video -->
                ${mediaHtml}

                <!-- 0/5 STAR RATING BAR -->
                <div class="mt-3.5 pt-3 border-t border-slate-100 dark:border-[#2A3C42] flex flex-wrap items-center justify-between gap-2">
                  <div class="flex items-center gap-1.5 flex-wrap">
                    <span class="text-xs font-bold text-amber-500 flex items-center gap-1">
                      ⭐ Đánh giá (0-5 sao):
                    </span>
                    <div class="flex items-center gap-1">
                      ${starButtonsHtml}
                    </div>
                  </div>
                  <div class="text-xs font-bold text-slate-600 dark:text-slate-300 bg-amber-50 dark:bg-amber-950/40 px-2.5 py-1 rounded-full border border-amber-200/70 dark:border-amber-800/50">
                    Trung bình: <span class="text-amber-600 dark:text-amber-400">${avgRating} / 5.0 ★</span> (${post.ratingCount} lượt)
                  </div>
                </div>

                <!-- Post Footer Actions: Comments, Share -->
                <div class="mt-3 flex items-center gap-3 text-xs font-semibold text-slate-500 dark:text-slate-400">
                  <button
                    type="button"
                    onclick="toggleComments('${post.id}')"
                    class="px-3 py-1.5 rounded-full bg-slate-100 dark:bg-[#0B1416] hover:bg-slate-200 dark:hover:bg-[#22333A] flex items-center gap-1.5 transition"
                  >
                    <span>💬</span>
                    <span>${post.comments.length} Bình luận</span>
                  </button>
                  <button
                    type="button"
                    onclick="sharePost('${post.id}')"
                    class="px-3 py-1.5 rounded-full bg-slate-100 dark:bg-[#0B1416] hover:bg-slate-200 dark:hover:bg-[#22333A] flex items-center gap-1.5 transition"
                  >
                    <span>🔗</span>
                    <span>Chia sẻ</span>
                  </button>
                </div>

                <!-- EXPANDABLE COMMENTS SECTION -->
                <div id="comments-box-${post.id}" class="${post.commentsExpanded ? '' : 'hidden'} mt-3 pt-3 border-t border-slate-100 dark:border-[#2A3C42] space-y-3">
                  <div class="flex gap-2">
                    <input
                      id="comment-input-${post.id}"
                      type="text"
                      placeholder="Viết bình luận của bạn dưới tên @${escapeHtml(currentUser.username)}..."
                      onkeydown="if(event.key==='Enter'){event.preventDefault();addComment('${post.id}');}"
                      class="flex-1 px-3.5 py-2 rounded-xl bg-slate-50 dark:bg-[#0B1416] border border-slate-200 dark:border-[#2A3C42] text-xs sm:text-sm focus:outline-none focus:ring-2 focus:ring-[#FF4500]"
                    >
                    <button
                      type="button"
                      onclick="addComment('${post.id}')"
                      class="px-4 py-2 rounded-xl bg-[#FF4500] hover:bg-[#E03D00] text-white text-xs font-bold shrink-0 transition"
                    >
                      Gửi
                    </button>
                  </div>
                  <div class="space-y-2">
                    ${commentsHtml || '<div class="text-xs text-slate-400 italic">Chưa có bình luận nào. Hãy là người đầu tiên bình luận!</div>'}
                  </div>
                </div>

              </div>
            </div>
          </article>
        `;
      }).join('');
    }

    // -------------------------------------------------------------------------
    // 9. INTERACTIONS: UPVOTE/DOWNVOTE, 0-5 STAR RATING, COMMENTS
    // -------------------------------------------------------------------------
    function votePost(postId, direction) {
      if (!currentUser.isLoggedIn) {
        showToast('Vui lòng đăng nhập tài khoản để Upvote / Downvote!', '🔒');
        openAuthModal();
        return;
      }
      const post = posts.find(p => p.id === postId);
      if (!post) return;

      if (post.userVote === direction) {
        post.score -= direction;
        post.userVote = 0;
      } else {
        post.score += direction - post.userVote;
        post.userVote = direction;

        // Push notification if voting on a post
        const actionLabel = direction === 1 ? 'upvote ⬆️' : 'downvote ⬇️';
        pushNotification({
          actor: `${currentUser.displayName} (@${currentUser.username})`,
          type: direction === 1 ? 'upvote' : 'downvote',
          icon: direction === 1 ? '⬆️' : '⬇️',
          text: `Bạn vừa ${actionLabel} bài đăng "${post.title}".`,
          postId: post.id
        });
      }
      renderFeed();
    }

    function ratePost(postId, stars) {
      if (!currentUser.isLoggedIn) {
        showToast('Vui lòng đăng nhập để đánh giá 0-5 sao!', '🔒');
        openAuthModal();
        return;
      }
      const post = posts.find(p => p.id === postId);
      if (!post) return;

      if (post.userRating !== null && post.userRating !== undefined) {
        post.ratingSum = post.ratingSum - post.userRating + stars;
      } else {
        post.ratingSum += stars;
        post.ratingCount += 1;
      }
      post.userRating = stars;

      pushNotification({
        actor: `${currentUser.displayName} (@${currentUser.username})`,
        type: 'rating',
        icon: '⭐',
        text: `đã chấm ${stars}/5 sao cho bài đăng "${post.title}".`,
        postId: post.id
      });

      showToast(`Đã đánh giá ${stars}/5 ⭐ cho bài viết!`, '⭐');
      renderFeed();
    }

    function toggleComments(postId) {
      const post = posts.find(p => p.id === postId);
      if (!post) return;
      post.commentsExpanded = !post.commentsExpanded;
      renderFeed();
    }

    function addComment(postId) {
      if (!currentUser.isLoggedIn) {
        showToast('Vui lòng đăng nhập để bình luận!', '🔒');
        openAuthModal();
        return;
      }
      const inputEl = document.getElementById('comment-input-' + postId);
      if (!inputEl) return;
      const text = inputEl.value.trim();
      if (!text) {
        showToast('Vui lòng nhập nội dung bình luận!', '⚠️');
        return;
      }
      const post = posts.find(p => p.id === postId);
      if (!post) return;

      post.comments.unshift({
        id: 'c_' + Date.now(),
        author: `${currentUser.displayName} (@${currentUser.username})`,
        text: text,
        time: 'Vừa xong',
        likes: 1
      });
      post.commentsExpanded = true;

      pushNotification({
        actor: `${currentUser.displayName} (@${currentUser.username})`,
        type: 'comment',
        icon: '💬',
        text: `đã bình luận vào "${post.title}": "${text.slice(0, 50)}"`,
        postId: post.id
      });

      showToast('Đã đăng bình luận!', '💬');
      renderFeed();
    }

    function sharePost(postId) {
      const post = posts.find(p => p.id === postId);
      if (!post) return;
      const dummy = document.createElement('textarea');
      dummy.value = window.location.href.split('#')[0] + '#post-' + postId;
      document.body.appendChild(dummy);
      dummy.select();
      try { document.execCommand('copy'); } catch (e) {}
      document.body.removeChild(dummy);
      showToast(`Đã sao chép liên kết bài đăng: "${post.title.slice(0, 30)}..."`, '🔗');
    }

    // -------------------------------------------------------------------------
    // 10. TOP-RIGHT NOTIFICATIONS BELL SYSTEM
    // -------------------------------------------------------------------------
    function renderNotifications() {
      const badge = document.getElementById('notifBadge');
      const listEl = document.getElementById('notifList');
      const unreadCount = notifications.filter(n => n.unread).length;

      if (badge) {
        if (unreadCount > 0) {
          badge.textContent = String(unreadCount);
          badge.classList.remove('hidden');
        } else {
          badge.classList.add('hidden');
        }
      }

      if (listEl) {
        if (notifications.length === 0) {
          listEl.innerHTML = `<div class="p-6 text-center text-xs text-slate-400">Không có thông báo mới.</div>`;
          return;
        }
        listEl.innerHTML = notifications.map(n => `
          <button
            type="button"
            onclick="openNotifTarget('${n.id}', '${n.postId}')"
            class="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-[#22333A] flex items-start gap-3 transition ${n.unread ? 'bg-orange-50/50 dark:bg-orange-950/20' : ''}"
          >
            <span class="text-lg shrink-0 mt-0.5">${n.icon}</span>
            <div class="flex-1 min-w-0">
              <p class="text-xs text-slate-800 dark:text-slate-200 leading-snug">
                <strong>${escapeHtml(n.actor)}</strong> ${escapeHtml(n.text)}
              </p>
              <span class="text-[10px] text-slate-400">${escapeHtml(n.time)}</span>
            </div>
            ${n.unread ? '<span class="w-2 h-2 rounded-full bg-[#FF4500] shrink-0 mt-1.5"></span>' : ''}
          </button>
        `).join('');
      }
    }

    function pushNotification(notifObj) {
      notifications.unshift({
        id: 'n_' + Date.now(),
        actor: notifObj.actor,
        type: notifObj.type,
        icon: notifObj.icon,
        text: notifObj.text,
        time: 'Vừa xong',
        unread: true,
        postId: notifObj.postId || 'p1'
      });
      renderNotifications();
    }

    function toggleNotifDropdown() {
      const dd = document.getElementById('notifDropdown');
      if (!dd) return;
      dd.classList.toggle('hidden');
      renderNotifications();
    }

    function markAllNotifsRead() {
      notifications.forEach(n => { n.unread = false; });
      renderNotifications();
      showToast('Đã đánh dấu đọc tất cả thông báo', '🔔');
    }

    function openNotifTarget(notifId, postId) {
      const notif = notifications.find(n => n.id === notifId);
      if (notif) notif.unread = false;
      const dd = document.getElementById('notifDropdown');
      if (dd) dd.classList.add('hidden');
      renderNotifications();
      scrollToPost(postId);
    }

    function simulateClassmateActivity() {
      const classmates = [
        'Nguyễn Minh Tuấn (@tuan_toan)',
        'Lê Thảo Vy (@thaovy_9a3)',
        'Trần Hoàng Nam (@nam_it)',
        'Huỳnh Ngọc Ánh (@ngocanh_bio)',
        'Đặng Quốc Bảo (@quocbao_9a3)'
      ];
      const randomMate = classmates[Math.floor(Math.random() * classmates.length)];
      const myPost = posts[1] || posts[0];
      const actions = [
        { type: 'upvote', icon: '⬆️', text: `vừa upvote bài đăng "${myPost.title}" của bạn!` },
        { type: 'rating', icon: '⭐', text: `vừa đánh giá 5/5 sao cho bài đăng "${myPost.title}" của bạn!` },
        { type: 'comment', icon: '💬', text: `vừa bình luận vào bài của bạn: "Bài viết chất lượng quá bạn ơi!"` }
      ];
      const chosen = actions[Math.floor(Math.random() * actions.length)];
      if (chosen.type === 'upvote') myPost.score += 1;
      if (chosen.type === 'rating') { myPost.ratingSum += 5; myPost.ratingCount += 1; }
      if (chosen.type === 'comment') {
        myPost.comments.unshift({
          id: 'c_sim_' + Date.now(),
          author: randomMate,
          text: 'Bài viết chất lượng quá bạn ơi!',
          time: 'Vừa xong',
          likes: 1
        });
      }
      pushNotification({
        actor: randomMate,
        type: chosen.type,
        icon: chosen.icon,
        text: chosen.text,
        postId: myPost.id
      });
      renderFeed();
      showToast(`${randomMate} ${chosen.text}`, chosen.icon);
    }

    // -------------------------------------------------------------------------
    // 11. CREATE POST MODAL & <100MB IMAGE / VIDEO UPLOAD VALIDATION
    // -------------------------------------------------------------------------
    function openCreatePostModal(defaultTag) {
      if (!currentUser.isLoggedIn) {
        showToast('Bạn cần đăng ký / đăng nhập tài khoản trước khi đăng bài!', '🔒');
        openAuthModal();
        return;
      }
      const modal = document.getElementById('createPostModal');
      const tagSelect = document.getElementById('postTagSelect');
      if (tagSelect && defaultTag) {
        tagSelect.value = defaultTag;
      }
      if (modal) modal.classList.remove('hidden');
    }

    function closeCreatePostModal() {
      const modal = document.getElementById('createPostModal');
      if (modal) modal.classList.add('hidden');
    }

    function handlePostMediaSelect(event) {
      const file = event.target.files && event.target.files[0];
      if (!file) return;

      const maxBytes = 100 * 1024 * 1024; // 100MB limit requested by user
      const sizeMB = (file.size / (1024 * 1024)).toFixed(2);

      if (file.size > maxBytes) {
        showToast(`File nặng ${sizeMB}MB (vượt quá giới hạn 100MB)! Vui lòng chọn file dưới 100MB.`, '❌');
        event.target.value = '';
        return;
      }

      const isVideo = file.type.startsWith('video/');
      const objectUrl = URL.createObjectURL(file);

      pendingMedia = {
        type: isVideo ? 'video' : 'image',
        url: objectUrl,
        name: file.name,
        sizeMB: `${sizeMB} MB`
      };

      const previewBox = document.getElementById('mediaPreviewContainer');
      const infoEl = document.getElementById('mediaFileInfo');
      const imgEl = document.getElementById('mediaPreviewImage');
      const vidEl = document.getElementById('mediaPreviewVideo');

      if (previewBox) previewBox.classList.remove('hidden');
      if (infoEl) infoEl.textContent = `✅ Đã chọn: ${file.name} (${sizeMB} MB / tối đa 100 MB)`;

      if (isVideo) {
        if (imgEl) imgEl.classList.add('hidden');
        if (vidEl) {
          vidEl.src = objectUrl;
          vidEl.classList.remove('hidden');
        }
      } else {
        if (vidEl) vidEl.classList.add('hidden');
        if (imgEl) {
          imgEl.src = objectUrl;
          imgEl.classList.remove('hidden');
        }
      }
      showToast(`Đã tải lên ${isVideo ? 'video' : 'ảnh'} (${sizeMB} MB)`, '📂');
    }

    function clearSelectedMedia() {
      pendingMedia = null;
      const fileInput = document.getElementById('postMediaInput');
      const previewBox = document.getElementById('mediaPreviewContainer');
      if (fileInput) fileInput.value = '';
      if (previewBox) previewBox.classList.add('hidden');
    }

    function submitNewPost(event) {
      event.preventDefault();
      const titleEl = document.getElementById('postTitleInput');
      const tagEl = document.getElementById('postTagSelect');
      const contentEl = document.getElementById('postContentInput');

      const title = titleEl ? titleEl.value.trim() : '';
      const tag = tagEl ? tagEl.value : 'Hỏi đáp';
      const content = contentEl ? contentEl.value.trim() : '';

      if (!title || !content) {
        showToast('Vui lòng điền đầy đủ tiêu đề và nội dung!', '⚠️');
        return;
      }

      const newPost = {
        id: 'post_' + Date.now(),
        isAnnouncement: tag === 'Thông báo',
        title: title,
        content: content,
        tag: tag,
        authorName: currentUser.displayName,
        authorUsername: currentUser.username,
        authorAvatar: currentUser.avatar,
        createdAt: Date.now(),
        timeLabel: 'Vừa xong',
        score: 1,
        userVote: 1,
        ratingSum: 5,
        ratingCount: 1,
        userRating: 5,
        media: pendingMedia ? { ...pendingMedia } : null,
        commentsExpanded: false,
        comments: []
      };

      posts.unshift(newPost);

      if (titleEl) titleEl.value = '';
      if (contentEl) contentEl.value = '';
      clearSelectedMedia();
      closeCreatePostModal();

      activeTag = 'Tất cả';
      sortMode = 'new';
      renderTagBars();
      renderFeed();
      showToast(`Đã đăng bài mới vào mục [${tag}]!`, '🎉');
    }

    // -------------------------------------------------------------------------
    // 12. AUTHENTICATION & PROFILE CUSTOMIZATION
    // -------------------------------------------------------------------------
    function renderUserHeaderAndSidebar() {
      const headerAvatar = document.getElementById('headerUserAvatar');
      const headerDisplay = document.getElementById('headerDisplayName');
      const headerUser = document.getElementById('headerUsername');
      const createBarAvatar = document.getElementById('createBarAvatar');

      const sideAvatar = document.getElementById('sidebarUserAvatar');
      const sideDisplay = document.getElementById('sidebarDisplayName');
      const sideUser = document.getElementById('sidebarUsername');
      const sideCover = document.getElementById('sidebarCoverBanner');
      const sideBadges = document.getElementById('sidebarLinkedBadges');
      const sideStatus = document.getElementById('sidebarAuthStatusBadge');

      if (headerAvatar) headerAvatar.src = currentUser.avatar;
      if (createBarAvatar) createBarAvatar.src = currentUser.avatar;
      if (headerDisplay) headerDisplay.textContent = currentUser.isLoggedIn ? currentUser.displayName : 'Đăng nhập';
      if (headerUser) headerUser.textContent = currentUser.isLoggedIn ? `@${currentUser.username}` : 'Bấm để tạo TK';

      if (sideAvatar) sideAvatar.src = currentUser.avatar;
      if (sideDisplay) sideDisplay.textContent = currentUser.displayName;
      if (sideUser) sideUser.textContent = `@${currentUser.username} • ${currentUser.role || 'Thành viên 9A3'}`;

      if (sideCover) {
        if (currentUser.cover && currentUser.cover.startsWith('data:') || (currentUser.cover && currentUser.cover.startsWith('blob:'))) {
          sideCover.style.backgroundImage = `url('${currentUser.cover}')`;
        } else if (currentUser.cover) {
          sideCover.style.backgroundImage = currentUser.cover;
        }
      }

      if (sideStatus) {
        sideStatus.textContent = currentUser.isLoggedIn ? 'Đã xác thực' : 'Khách';
      }

      if (sideBadges) {
        sideBadges.innerHTML = (currentUser.linkedProviders || []).map(p => {
          const badgeColor = p === 'Google'
            ? 'bg-red-50 text-red-600 border-red-200 dark:bg-red-950/60 dark:text-red-300 dark:border-red-800'
            : p === 'Facebook'
              ? 'bg-blue-50 text-blue-600 border-blue-200 dark:bg-blue-950/60 dark:text-blue-300 dark:border-blue-800'
              : 'bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-950/60 dark:text-amber-300 dark:border-amber-800';
          return `<span class="text-[10px] font-bold px-2 py-0.5 rounded-md border ${badgeColor}">✓ Đã liên kết ${p}</span>`;
        }).join('');
      }
    }

    function handleUserHeaderClick() {
      if (currentUser.isLoggedIn) {
        openProfileModal();
      } else {
        openAuthModal();
      }
    }

    function openAuthModal() {
      const modal = document.getElementById('authModal');
      if (modal) modal.classList.remove('hidden');
    }

    function closeAuthModal() {
      const modal = document.getElementById('authModal');
      if (modal) modal.classList.add('hidden');
    }

    function socialLogin(provider) {
      currentUser.isLoggedIn = true;
      if (!currentUser.linkedProviders.includes(provider)) {
        currentUser.linkedProviders.push(provider);
      }
      saveUserState();
      renderUserHeaderAndSidebar();
      closeAuthModal();
      showToast(`Đã đăng nhập & liên kết thành công với ${provider}!`, '🔗');
    }

    function submitAuthForm(event) {
      event.preventDefault();
      const uInput = document.getElementById('authUsernameInput');
      const dInput = document.getElementById('authDisplayNameInput');
      const eInput = document.getElementById('authEmailInput');

      const rawUser = uInput ? uInput.value.trim().replace(/^@/, '') : 'hocsinh_9a3';
      const dispName = dInput ? dInput.value.trim() : 'Thành viên 9A3';
      const email = eInput ? eInput.value.trim() : '';

      const initials = dispName.split(' ').map(w => w[0]).join('').slice(0, 2).toUpperCase() || '9A';

      currentUser.isLoggedIn = true;
      currentUser.username = rawUser;
      currentUser.displayName = dispName;
      currentUser.email = email;
      currentUser.avatar = makeAvatarDataUri(initials, '#FF4500');
      if (!currentUser.linkedProviders.includes('Gmail')) {
        currentUser.linkedProviders.push('Gmail');
      }

      saveUserState();
      renderUserHeaderAndSidebar();
      renderFeed();
      closeAuthModal();
      showToast(`Chào mừng ${dispName} (@${rawUser}) gia nhập r/9A3AnChau!`, '🎉');
    }

    function openProfileModal() {
      const modal = document.getElementById('profileModal');
      const dInput = document.getElementById('editDisplayName');
      const uInput = document.getElementById('editUsername');
      const rInput = document.getElementById('editRole');
      const prevAvatar = document.getElementById('profilePreviewAvatar');
      const prevCover = document.getElementById('profilePreviewCover');

      if (dInput) dInput.value = currentUser.displayName;
      if (uInput) uInput.value = currentUser.username;
      if (rInput) rInput.value = currentUser.role || 'Thành viên 9A3';
      if (prevAvatar) prevAvatar.src = currentUser.avatar;

      if (prevCover && currentUser.cover) {
        if (currentUser.cover.startsWith('data:') || currentUser.cover.startsWith('blob:')) {
          prevCover.style.backgroundImage = `url('${currentUser.cover}')`;
        } else {
          prevCover.style.backgroundImage = currentUser.cover;
        }
      }

      updateProfileModalProviderButtons();
      if (modal) modal.classList.remove('hidden');
    }

    function closeProfileModal() {
      const modal = document.getElementById('profileModal');
      if (modal) modal.classList.add('hidden');
    }

    function updateProfileModalProviderButtons() {
      ['Google', 'Facebook', 'Gmail'].forEach(provider => {
        const btn = document.getElementById('link' + provider + 'Btn');
        if (!btn) return;
        const linked = currentUser.linkedProviders.includes(provider);
        if (linked) {
          btn.className = 'px-3 py-1.5 rounded-lg text-xs font-bold border bg-emerald-500 text-white border-emerald-600 transition';
          btn.textContent = `✓ Đã liên kết ${provider}`;
        } else {
          btn.className = 'px-3 py-1.5 rounded-lg text-xs font-bold border bg-white dark:bg-[#1A282D] text-slate-600 dark:text-slate-300 border-slate-300 dark:border-[#2A3C42] transition';
          btn.textContent = `+ Liên kết ${provider}`;
        }
      });
    }

    function toggleProviderLink(provider) {
      const idx = currentUser.linkedProviders.indexOf(provider);
      if (idx >= 0) {
        currentUser.linkedProviders.splice(idx, 1);
        showToast(`Đã huỷ liên kết ${provider}`, 'ℹ️');
      } else {
        currentUser.linkedProviders.push(provider);
        showToast(`Đã liên kết tài khoản ${provider}!`, '🔗');
      }
      updateProfileModalProviderButtons();
      renderUserHeaderAndSidebar();
      saveUserState();
    }

    function handleAvatarUpload(event) {
      const file = event.target.files && event.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = function(e) {
        currentUser.avatar = e.target.result;
        const prevAvatar = document.getElementById('profilePreviewAvatar');
        if (prevAvatar) prevAvatar.src = currentUser.avatar;
        renderUserHeaderAndSidebar();
        saveUserState();
        showToast('Đã cập nhật Ảnh đại diện mới!', '📷');
      };
      reader.readAsDataURL(file);
    }

    function handleCoverUpload(event) {
      const file = event.target.files && event.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = function(e) {
        currentUser.cover = e.target.result;
        const prevCover = document.getElementById('profilePreviewCover');
        if (prevCover) prevCover.style.backgroundImage = `url('${currentUser.cover}')`;
        renderUserHeaderAndSidebar();
        saveUserState();
        showToast('Đã cập nhật Ảnh bìa mới!', '🖼️');
      };
      reader.readAsDataURL(file);
    }

    function selectPresetCover(presetKey) {
      const map = {
        orange: 'linear-gradient(90deg, #FF4500, #FF8C00)',
        blue: 'linear-gradient(90deg, #2563EB, #06B6D4)',
        purple: 'linear-gradient(90deg, #7C3AED, #EC4899)',
        green: 'linear-gradient(90deg, #059669, #10B981)'
      };
      const gradientCss = map[presetKey] || map.orange;
      currentUser.cover = gradientCss;
      const prevCover = document.getElementById('profilePreviewCover');
      if (prevCover) prevCover.style.backgroundImage = gradientCss;
      renderUserHeaderAndSidebar();
      saveUserState();
      showToast('Đã đổi màu Ảnh bìa!', '🎨');
    }

    function saveProfileChanges(event) {
      event.preventDefault();
      const dInput = document.getElementById('editDisplayName');
      const uInput = document.getElementById('editUsername');
      const rInput = document.getElementById('editRole');

      if (dInput && dInput.value.trim()) currentUser.displayName = dInput.value.trim();
      if (uInput && uInput.value.trim()) currentUser.username = uInput.value.trim().replace(/^@/, '');
      if (rInput) currentUser.role = rInput.value.trim() || 'Thành viên 9A3';

      saveUserState();
      renderUserHeaderAndSidebar();
      renderFeed();
      closeProfileModal();
      showToast('Đã lưu thông tin hồ sơ tài khoản!', '💾');
    }

    // -------------------------------------------------------------------------
    // 13. DEPLOY GUIDE MODAL
    // -------------------------------------------------------------------------
    function openDeployGuideModal() {
      const m = document.getElementById('deployGuideModal');
      if (m) m.classList.remove('hidden');
    }

    function closeDeployGuideModal() {
      const m = document.getElementById('deployGuideModal');
      if (m) m.classList.add('hidden');
    }

    // Close notification dropdown when clicking outside
    document.addEventListener('click', function(e) {
      const notifBtn = document.getElementById('notifBtn');
      const notifDropdown = document.getElementById('notifDropdown');
      if (notifBtn && notifDropdown && !notifDropdown.classList.contains('hidden')) {
        if (!notifBtn.contains(e.target) && !notifDropdown.contains(e.target)) {
          notifDropdown.classList.add('hidden');
        }
      }
    });

    // -------------------------------------------------------------------------
    // 14. INITIALIZE APP ON LOAD
    // -------------------------------------------------------------------------
    window.addEventListener('DOMContentLoaded', function() {
      loadSavedState();
      updateThemeButtonUI();
      renderUserHeaderAndSidebar();
      renderTagBars();
      renderNotifications();
      renderFeed();
    });
